"use server";

import { redirect } from "next/navigation";
import { db } from "@/lib/db";
import { createSession, destroySession } from "@/lib/session";
import { hashPassword, verifyPassword } from "@/lib/auth";
import { mergeGuestCart } from "@/lib/cart";
import { rateLimit } from "@/lib/security";
import { loginSchema, registerSchema } from "@/lib/validators";

export type FormState = { error?: string; fieldErrors?: Record<string, string[] | undefined>; ok?: boolean } | undefined;

// Only allow same-site relative redirects after login (prevents open redirects).
function safeNext(next: FormDataEntryValue | null) {
  const n = typeof next === "string" ? next : "";
  return n.startsWith("/") && !n.startsWith("//") && !n.startsWith("/\\") ? n : "/account";
}

// Constant-time-ish failure path so response time doesn't reveal whether an email exists.
const DUMMY_HASH = "$2b$12$C6UzMDM.H6dfI/f/IKcEeO5Hc3SUMB7a6oG7yKkDB1sQx1jJv0Qma";

export async function login(_: FormState, formData: FormData): Promise<FormState> {
  if (!(await rateLimit("login", 10, 15 * 60))) return { error: "Too many attempts. Please try again in 15 minutes." };
  const parsed = loginSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { fieldErrors: parsed.error.flatten().fieldErrors };

  // Per-account limit stops distributed password guessing against one email.
  if (!(await rateLimit("login-acct", 8, 15 * 60, parsed.data.email))) return { error: "Too many attempts for this account. Please try again in 15 minutes or reset your password." };
  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
  const valid = await verifyPassword(parsed.data.password, user?.passwordHash ?? DUMMY_HASH);
  if (!user || !valid || !user.isActive) return { error: "Incorrect email or password." };

  await createSession(user.id);
  await db.user.update({ where: { id: user.id }, data: { lastLoginAt: new Date() } });
  await mergeGuestCart(user.id);
  const next = safeNext(formData.get("next"));
  redirect(user.role !== "CUSTOMER" && next === "/account" ? "/admin" : next);
}

export async function register(_: FormState, formData: FormData): Promise<FormState> {
  if (!(await rateLimit("register", 5, 60 * 60))) return { error: "Too many sign-ups from this network. Please try later." };
  const parsed = registerSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { fieldErrors: parsed.error.flatten().fieldErrors };

  const exists = await db.user.findUnique({ where: { email: parsed.data.email } });
  if (exists) return { fieldErrors: { email: ["An account with this email already exists. Please sign in."] } };

  const user = await db.user.create({
    data: { name: parsed.data.name, email: parsed.data.email, phone: parsed.data.phone, passwordHash: await hashPassword(parsed.data.password) },
  });
  await createSession(user.id);
  await mergeGuestCart(user.id);
  redirect(safeNext(formData.get("next")));
}

export async function logout() {
  await destroySession();
  redirect("/");
}
